pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Record state before calling XBornID()
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 totalDistributedBefore = c.totalDistributed();

        // Call XBornID()
        c.XBornID();

        // Record state after calling XBornID()
        uint256 totalSupplyAfter = c.totalSupply();
        uint256 totalDistributedAfter = c.totalDistributed();

        // General rule: totalSupply - totalDistributed remains unchanged after XBornID()
        // For the reference C: XBornID() sets balances[owner] = totalDistributed without modifying totalSupply or totalDistributed
        // For the mutant: is not relevant here; the rule holds for both because XBornID doesn't call burn
        // Actually the difference is in burn; we need to test burn behavior.
        // Re-evaluate: The difference is in burn; test that burn does not increase totalSupply.
        // But the prompt says "after a call to XBornID() completes, the value of totalSupply differs". 
        // That seems to imply the difference manifests only after XBornID(). 
        // Let's think: XBornID sets balances[owner] = totalDistributed. The reference burn decreases totalSupply, mutant increases it.
        // The rule could be: burning tokens never increases totalSupply.
        // But we need to drive through XBornID. The original problem says: "Driven through the public/external entry XBornID(), P and M differ in way: after call to XBornID(), totalSupply differs".
        // Actually XBornID does not change totalSupply in either version. So perhaps the idea is that XBornID triggers some transfer that eventually leads to a burn? No.
        // The given example may be misleading. Let's stick to the intended property: after burn, totalSupply should not increase.
        // We'll test the burn function directly via fuzzing.
    }
}

