pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 burnValue) public {
        uint256 initialSupply = c.totalSupply();
        vm.assume(burnValue > 0 && burnValue <= c.balanceOf(address(c.owner())));

        // Call burn through the onlyOwner path: we need to set msg.sender as owner
        // But owner is set in constructor to msg.sender (this contract).
        // So we can call burn directly as we are the owner.
        // However, XBornID() is called first to establish balances.
        c.XBornID();

        // Now call burn
        c.burn(burnValue);

        uint256 newSupply = c.totalSupply();

        // The rule: totalSupply should decrease by burnValue (or stay same if burnValue is 0)
        assertTrue(newSupply == initialSupply - burnValue, "totalSupply should decrease by burnValue");
    }
}

