pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address investor, uint256 valueMultiplier) public {
        // Ensure valueMultiplier is reasonable to avoid overflow
        vm.assume(valueMultiplier > 0 && valueMultiplier <= 1e12);
        // Simulate a call to getTokens() to potentially change totalDistributed
        if (investor != address(0) && c.blacklist(investor) == false && c.distributionFinished() == false) {
            vm.deal(investor, 1 ether);
            vm.prank(investor);
            // We'll call getTokens() multiple times with different investors to stir state
            c.getTokens();
        }
        // Call XBornID() to reset totalDistributed (in reference)
        c.XBornID();
        // The rule: totalDistributed should be >= 200000000e18 after XBornID()
        // In the reference, XBornID() sets totalDistributed to that value.
        // In the mutant, the swap may cause totalDistributed to be lower if previous getTokens() incremented it.
        assertTrue(c.totalDistributed() >= 200000000e18);
    }
}

