// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Precondition: amount must not exceed totalRemaining
        uint256 totalRemaining = c.totalRemaining();
        vm.assume(amount <= totalRemaining && amount > 0);

        // Record initial totalDistributed
        uint256 initialTotalDistributed = c.totalDistributed();

        // Call XBornID() to set up initial balances
        c.XBornID();

        // After XBornID, totalDistributed should equal totalDistributed (which is set to totalDistributed)
        // Actually XBornID sets balances[owner] = totalDistributed, does not change totalDistributed
        // So we need to distribute via distr through getTokens
        // But getTokens is payable and canDistr, so we need to call it
        // However getTokens uses value and blacklist, so we need to handle that
        // The simplest way is to directly call the private distr via getTokens
        // But we can only interact via public functions
        // So we call getTokens with the appropriate value
        vm.deal(address(c), amount);
        (bool success, ) = address(c).call{value: amount}("");
        require(success, "call failed");

        // The call triggers getTokens which calls distr
        // distr should increase totalDistributed by amount (in reference)
        // In mutant, it does not
        uint256 finalTotalDistributed = c.totalDistributed();

        // Rule: totalDistributed should increase by amount
        assertTrue(finalTotalDistributed == initialTotalDistributed + amount);
    }
}

