pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // XBornID() requires msg.sender == owner in P, but in M it requires msg.sender != owner.
        // In P, any call by non-owner reverts; in M, any call by owner reverts.
        // After a successful call (which can only happen if msg.sender is owner in P,
        // or non-owner in M), the owner remains the deployer (address(this)).
        // So the general rule: calling XBornID() either reverts or leaves owner unchanged.
        address ownerBefore = c.owner();
        (bool success, ) = address(c).call(abi.encodeWithSignature("XBornID()"));
        address ownerAfter = c.owner();
        assertTrue(success || ownerBefore == ownerAfter);
    }
}

