pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bool isFinishedBefore, uint256 timeOffset) public {
        // bound timeOffset to avoid overflow in warp (no actual warp needed)
        vm.assume(caller != address(0));
        // If distribution is already finished, finishDistribution will revert in both P and M due to canDistr modifier.
        // So we only test when distribution is not finished.
        if (isFinishedBefore) {
            // Make it finished by calling finishDistribution as owner
            // Owner is the deployer (this contract)
            vm.prank(address(this));
            c.finishDistribution();
        }
        // Now call finishDistribution as caller (must be owner to avoid onlyOwner revert)
        vm.prank(caller);
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSignature("finishDistribution()"));
        if (!success) {
            // If it reverted, both P and M should revert (onlyOwner or canDistr), so rule holds.
            assertTrue(true);
        } else {
            // It succeeded. Decode return value.
            bool retVal = abi.decode(ret, (bool));
            // The rule: when finishDistribution completes without revert, it must return true.
            assertTrue(retVal == true);
        }
    }
}

