pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 ethAmount) public {
        // Bound ethAmount to a reasonable range (e.g., up to 1000 ether)
        vm.assume(ethAmount <= 1000 ether);
        // Give the caller some ETH to pay for getTokens()
        vm.deal(caller, ethAmount);

        // Call XBornID() first to set up initial balances
        c.XBornID();

        // Record the balance of the caller before getTokens()
        uint256 balanceBefore = c.balanceOf(caller);

        // Call getTokens() via the caller
        vm.prank(caller);
        (bool success, ) = address(c).call{value: ethAmount}(abi.encodeWithSignature("getTokens()"));

        // Get the balance after
        uint256 balanceAfter = c.balanceOf(caller);

        // The general rule: if the call succeeded, the caller's balance must have increased
        assertTrue(!success || balanceAfter > balanceBefore);
    }
}

