pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.startPrank(caller);

        // Capture totalDistributed before XBornID
        uint256 totalDistributedBefore = c.totalDistributed();

        // Call XBornID
        c.XBornID();

        // After XBornID, getTokens() distributes tokens to caller.
        // The reference contract sets value = totalRemaining if value > totalRemaining.
        // The mutant sets value = 0 in that case, so totalDistributed doesn't change.
        // The rule: After XBornID, either value <= totalRemaining (so value unchanged) 
        // or totalDistributed increased by at least the original value (since in reference it increases).
        // Simpler: For reference, if value > totalRemaining before getTokens, then after getTokens totalDistributed == totalDistributedBefore + totalRemaining.
        // But we can't access totalRemaining directly (it's public? Actually totalRemaining is public, yes).
        // Let's use a simpler rule: check that after XBornID, totalDistributed >= totalDistributedBefore + value (if value > totalRemaining, reference distributes totalRemaining which is >= value? No, totalRemaining could be less).
        // Better: After XBornID, if value > totalRemaining then totalDistributed == totalDistributedBefore + totalRemaining (before getTokens). But value changes inside getTokens.
        // We'll use the fact that in reference, getTokens always distributes some positive amount if value > 0 and totalRemaining > 0.
        // Simpler: After XBornID, totalDistributed > totalDistributedBefore if value > 0 and totalRemaining > 0 before the call.
        uint256 totalDistributedAfter = c.totalDistributed();
        uint256 valueBefore = c.value();
        uint256 totalRemainingBefore = c.totalRemaining();

        // The rule: if valueBefore > 0 and totalRemainingBefore > 0, then totalDistributedAfter > totalDistributedBefore
        bool rule = (valueBefore == 0 || totalRemainingBefore == 0) || (totalDistributedAfter > totalDistributedBefore);
        assertTrue(rule);

        vm.stopPrank();
    }
}

