import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _initialValue) public {
        _initialValue = bound(_initialValue, 1, 1e36);
        // Set value to a value greater than totalRemaining to trigger the branch
        uint256 totalRemainingBefore = c.totalRemaining();
        vm.assume(_initialValue > totalRemainingBefore);
        // Use vm.store to set the value state variable (address slot 7 in default layout)
        vm.store(address(c), bytes32(uint256(7)), bytes32(_initialValue));
        // Call XBornID to trigger the bug
        c.XBornID();
        // After the call, in the reference value should be totalRemainingBefore, in mutant it will be 0
        uint256 valueAfter = c.value();
        // The rule: if _initialValue > totalRemainingBefore, then valueAfter should equal totalRemainingBefore
        assertTrue(valueAfter == totalRemainingBefore);
    }
}

