pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr) public {
        // Call XBornID() to set balances[owner] = totalDistributed
        c.XBornID();
        // The rule: balanceOf(addr) should equal the balance stored in the mapping
        // We cannot directly read balances, but we can compute totalDistributed and totalSupply
        // from public getters and use the invariant that totalDistributed = totalSupply - totalRemaining
        // However, after XBornID(), balances[owner] = totalDistributed, and all other balances are 0.
        // So the rule simplifies to: if addr == owner, balanceOf(addr) == totalDistributed; else balanceOf(addr) == 0.
        // To avoid internal state, we use the public getter totalDistributed and compare.
        uint256 expected = (addr == address(this) ? c.totalDistributed() : 0);
        assertTrue(c.balanceOf(addr) == expected);
    }
}
